/* Ritme service worker.
 *
 * Generated by scripts/generate-version.mjs — do not edit public/sw.js
 * directly; edit scripts/sw.template.js instead. APP_VERSION and BUILD_ID
 * below are stamped on every build, so every deploy (even one that did
 * not bump package.json) ships a byte-different worker: the browser fires
 * `updatefound`, which drives the in-app update toast, refreshes the precache
 * and runs the old-cache cleanup below.
 *
 * Caching policy:
 *  - Precache (per build): offline page, icons, manifest.
 *  - Navigations: network-first (navigation preload + timeout) → offline.html.
 *  - /_next/static/* (content-hashed, immutable): cache-first.
 *  - Other static assets (icons, fonts, images): stale-while-revalidate.
 *  - Runtime cache is capped at RUNTIME_MAX_ENTRIES (oldest evicted first).
 *  - /{locale}/learn/downloads (B-N8-04): network-first, last good copy kept
 *    for offline playback of downloaded lessons.
 *  - NEVER cached: /api/* (health data — privacy, CLAUDE.md §11), version.json
 *    (update source of truth), sw.js itself, and other HTML documents.
 */

const APP_VERSION = '__APP_VERSION__';
const BUILD_ID = '__BUILD_ID__';
const PRECACHE = `ritme-precache-v${APP_VERSION}-${BUILD_ID}`;
// Deliberately NOT per build: hashed chunks keep their names across deploys,
// and keeping the previous build's chunks lets a tab that is still on the old
// HTML finish loading them. The entry cap keeps it bounded instead.
const RUNTIME = 'ritme-runtime-v2';
const RUNTIME_MAX_ENTRIES = 150;
const OFFLINE_URL = '/offline.html';
// A stalled connection (VPN / filtering) must end on the offline page, not a
// blank screen that spins forever.
const NAVIGATION_TIMEOUT_MS = 10000;
// B-N8-04 offline lessons: the downloads screen document (per locale). The
// downloaded media itself lives encrypted in IndexedDB (shared/pwa/offline/offline-media.ts),
// never in Cache Storage, so a worker update can't purge it. This cache is not
// per build, so the activate cleanup below keeps it.
const OFFLINE_PAGES = 'ritme-offline-pages-v1';
const DOWNLOADS_PAGE = /^\/[a-z]{2,3}(?:-[A-Za-z]{2,4})?\/learn\/downloads\/?$/;

const PRECACHE_URLS = [
  OFFLINE_URL,
  '/manifest.webmanifest',
  '/logo.webp',
  '/icons/icon-192.png',
  '/icons/icon-512.png',
  '/icons/maskable-192.png',
  '/icons/maskable-512.png',
  '/icons/apple-touch-icon.png',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(PRECACHE)
      // `reload` skips the HTTP cache so a new build never precaches a stale copy.
      .then((cache) => cache.addAll(PRECACHE_URLS.map((url) => new Request(url, { cache: 'reload' })))),
  );
  // Do NOT skipWaiting here — activation is user-driven via the update button.
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // Every cache that is not this build's precache or the shared runtime
      // cache belongs to an older worker: drop it.
      const keys = await caches.keys();
      await Promise.all(
        keys.filter((key) => key !== PRECACHE && key !== RUNTIME && key !== OFFLINE_PAGES).map((key) => caches.delete(key)),
      );
      if (self.registration.navigationPreload) {
        await self.registration.navigationPreload.enable().catch(() => undefined);
      }
      // Claiming makes the first visit controlled (so offline works right away).
      // The page only reloads on controllerchange if it was controlled at load
      // or the user pressed "update" — see shared/pwa/useAppUpdate.ts.
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
  if (event.data?.type === 'CLEAR_RUNTIME_CACHE') {
    event.waitUntil(caches.delete(RUNTIME));
  }
});

// ---------------------------------------------------------------------------
// Web Push (medication reminders). The server sends JSON
// {"title","body","url","tag"}; `url` is an in-app path such as /fa/reminders.
// Privacy (CLAUDE.md §11): the notification text is health data — it is shown
// and then forgotten, never logged, never cached, never written anywhere.
// ---------------------------------------------------------------------------
const PUSH_FALLBACK_TITLE = '\u0631\u06cc\u062a\u0645\u06cc';
const PUSH_DEFAULT_TAG = 'ritme-reminder';
const RTL_LANGS = ['fa', 'ar', 'he', 'ur'];

// Same-origin in-app paths only: one leading "/", no protocol-relative or
// backslash tricks, no control characters. Anything else falls back to "/".
function safeAppPath(value) {
  if (typeof value !== 'string' || value.length === 0 || value.length > 2000) return '/';
  if (value[0] !== '/' || value[1] === '/' || value[1] === '\\') return '/';
  if (/[\u0000-\u001f\u007f]/.test(value)) return '/';
  try {
    const parsed = new URL(value, self.location.origin);
    if (parsed.origin !== self.location.origin) return '/';
    return parsed.pathname + parsed.search + parsed.hash;
  } catch {
    return '/';
  }
}

function pushText(value, max) {
  return typeof value === 'string' ? value.slice(0, max) : '';
}

function parsePush(event) {
  try {
    const raw = event.data ? event.data.json() : null;
    return raw && typeof raw === 'object' ? raw : {};
  } catch {
    return {};
  }
}

self.addEventListener('push', (event) => {
  const payload = parsePush(event);
  const title = pushText(payload.title, 200) || PUSH_FALLBACK_TITLE;
  const url = safeAppPath(payload.url);
  const lang = url.split('/')[1] || '';
  const options = {
    body: pushText(payload.body, 500),
    tag: pushText(payload.tag, 100) || PUSH_DEFAULT_TAG,
    icon: '/icons/icon-192.png',
    badge: '/icons/icon-192.png',
    data: { url },
    dir: RTL_LANGS.includes(lang.split('-')[0]) ? 'rtl' : 'ltr',
  };
  if (/^[a-z]{2,3}(?:-[A-Za-z]{2,4})?$/.test(lang)) options.lang = lang;
  // A push without a visible notification is penalised by browsers, so this
  // always shows one — a neutral one when the payload is missing or malformed.
  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const target = safeAppPath(event.notification.data && event.notification.data.url);
  const absolute = new URL(target, self.location.origin).href;
  event.waitUntil(
    (async () => {
      const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
      const existing = windows.find((client) => new URL(client.url).origin === self.location.origin);
      if (existing) {
        try {
          const focused = await existing.focus();
          const client = focused || existing;
          if (typeof client.navigate === 'function') await client.navigate(absolute);
          return;
        } catch {
          // Fall through to opening a fresh window.
        }
      }
      await self.clients.openWindow(absolute);
    })(),
  );
});

function isHashedAsset(url) {
  return url.pathname.startsWith('/_next/static/');
}

function isStaticAsset(url) {
  return (
    url.pathname.startsWith('/icons/') ||
    url.pathname.startsWith('/fonts/') ||
    /\.(?:png|webp|jpg|jpeg|svg|gif|ico|woff2?)$/.test(url.pathname)
  );
}

// Oldest-first eviction: Cache Storage returns keys in insertion order, and a
// re-put moves an entry to the end, so this approximates LRU-by-write.
async function trimRuntimeCache() {
  const cache = await caches.open(RUNTIME);
  const keys = await cache.keys();
  const excess = keys.length - RUNTIME_MAX_ENTRIES;
  if (excess <= 0) return;
  await Promise.all(keys.slice(0, excess).map((key) => cache.delete(key)));
}

async function putRuntime(request, response) {
  if (!response || !response.ok || response.type === 'opaque') return;
  const cache = await caches.open(RUNTIME);
  await cache.put(request, response);
  await trimRuntimeCache();
}

function withTimeout(promise, ms) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('navigation timeout')), ms);
    promise.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (error) => {
        clearTimeout(timer);
        reject(error);
      },
    );
  });
}

async function offlineResponse() {
  const cached = await caches.match(OFFLINE_URL);
  return cached ?? Response.error();
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Bypass entirely: API (health data must never rest in Cache Storage),
  // the version manifest, and the worker itself.
  if (
    url.pathname.startsWith('/api/') ||
    url.pathname === '/version.json' ||
    url.pathname === '/sw.js'
  ) {
    return;
  }

  // B-N8-04: the «دانلودها» screen is the one document kept for offline use,
  // so downloaded lessons stay playable without a connection. Its HTML is the
  // client shell only (no session, no health data — everything is rendered on
  // the client from IndexedDB). Network-first; a redirect/error is never stored.
  if (request.mode === 'navigate' && DOWNLOADS_PAGE.test(url.pathname)) {
    event.respondWith(
      (async () => {
        try {
          const network = (async () => (await event.preloadResponse) || fetch(request))();
          const response = await withTimeout(network, NAVIGATION_TIMEOUT_MS);
          if (response.ok && !response.redirected && response.type === 'basic') {
            const copy = response.clone();
            event.waitUntil(
              caches.open(OFFLINE_PAGES).then((cache) => cache.put(url.pathname, copy)).catch(() => undefined),
            );
          }
          return response;
        } catch {
          const cached = await caches.match(url.pathname, { cacheName: OFFLINE_PAGES });
          return cached ?? offlineResponse();
        }
      })(),
    );
    return;
  }

  // Navigations: network-first (never cached), offline fallback.
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          const network = (async () => (await event.preloadResponse) || fetch(request))();
          return await withTimeout(network, NAVIGATION_TIMEOUT_MS);
        } catch {
          return offlineResponse();
        }
      })(),
    );
    return;
  }

  // Content-hashed build output: the name changes whenever the bytes do, so a
  // cached copy is always correct — cache-first, no background refetch.
  if (isHashedAsset(url)) {
    event.respondWith(
      caches.match(request, { cacheName: RUNTIME }).then((cached) => {
        if (cached) return cached;
        return fetch(request).then((response) => {
          // Clone before handing the body to the page; the waitUntil call
          // happens while respondWith is still pending, which keeps it legal.
          event.waitUntil(putRuntime(request, response.clone()).catch(() => undefined));
          return response;
        });
      }),
    );
    return;
  }

  // Other static assets (unhashed names): stale-while-revalidate.
  if (isStaticAsset(url)) {
    const network = fetch(request).catch(() => undefined);
    // Registered first, so the clone happens before the page reads the body.
    const saved = network
      .then((response) => response && putRuntime(request, response.clone()))
      .catch(() => undefined);
    event.waitUntil(saved);
    event.respondWith(
      caches
        .match(request, { cacheName: RUNTIME })
        .then(async (cached) => cached ?? (await network) ?? Response.error()),
    );
  }
});
